query:
-- Limpar produtos duplicados (manter apenas o primeiro de cada)
DELETE FROM produtos WHERE id IN (
  SELECT id FROM (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY nome ORDER BY id) as rn
    FROM produtos
  ) t WHERE rn > 1
);

-- Verificar produtos restantes
SELECT id, nome FROM produtos ORDER BY id;

